contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance for deposit");

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint beforeUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;
        uint afterTestBalance = address(this).balance;

        assert(
            reverted == (beforeUserBalance > beforeContractBalance) ||
            (!reverted &&
             afterUserBalance == 0 &&
             beforeUserBalance <= beforeContractBalance &&
             afterContractBalance + beforeUserBalance == beforeContractBalance &&
             afterTestBalance == beforeTestBalance + beforeUserBalance)
        );
    }

    receive() external payable {}
}

