pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 beforeUserBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUserBalance = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUserBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUserBalance = __r; } catch { return; }
        uint afterContractBalance = address(c).balance;
        uint afterTestBalance = address(this).balance;
        assertTrue(reverted == (beforeUserBalance > beforeContractBalance) ||
            (!reverted &&
             afterUserBalance == 0 &&
             beforeUserBalance <= beforeContractBalance &&
             afterContractBalance + beforeUserBalance == beforeContractBalance &&
             afterTestBalance == beforeTestBalance + beforeUserBalance));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
